28 /**
29  * Basic implementation of the AWSCredentials interface that allows callers to
30  * pass in the AWS access key and secret access in the constructor.
31  */
32 class Credentials implements CredentialsInterface, FromConfigInterface
33 {
34     const ENV_KEY = 'AWS_ACCESS_KEY_ID';
35     const ENV_SECRET = 'AWS_SECRET_KEY';
36     const ENV_SECRET_ACCESS_KEY = 'AWS_SECRET_ACCESS_KEY';
37     const ENV_PROFILE = 'AWS_PROFILE';
38 
39     /** @var string AWS Access Key ID */
40     protected $key;
41 
42     /** @var string AWS Secret Access Key */
43     protected $secret;
44 
45     /** @var string AWS Security Token */
46     protected $token;
47 
48     /** @var int Time to die of token */
49     protected $ttd;
50 
51     /**
52      * Get the available keys for the factory method
53      *
54      * @return array
55      */
56     public static function getConfigDefaults()
57     {
58         return array(
59             Options::KEY                   => null,
60             Options::SECRET                => null,
61             Options::TOKEN                 => null,
62             Options::TOKEN_TTD             => null,
63             Options::PROFILE               => null,
64             Options::CREDENTIALS_CACHE     => null,
65             Options::CREDENTIALS_CACHE_KEY => null,
66             Options::CREDENTIALS_CLIENT    => null
67         );
68     }
69 
70     /**
71      * Factory method for creating new credentials.  This factory method will
72      * create the appropriate credentials object with appropriate decorators
73      * based on the passed configuration options.
74      *
75      * @param array $config Options to use when instantiating the credentials
76      *
77      * @return CredentialsInterface
78      * @throws InvalidArgumentException If the caching options are invalid
79      * @throws RuntimeException         If using the default cache and APC is disabled
80      */
81     public static function factory($config = array())
82     {
83         // Add default key values
84         foreach (self::getConfigDefaults() as $key => $value) {
85             if (!isset($config[$key])) {
86                 $config[$key] = $value;
87             }
88         }
89 
90         // Start tracking the cache key
91         $cacheKey = $config[Options::CREDENTIALS_CACHE_KEY];
92 
93         // Create the credentials object
94         if (!$config[Options::KEY] || !$config[Options::SECRET]) {
95             $credentials = self::createFromEnvironment($config);
96             // If no cache key was set, use the crc32 hostname of the server
97             $cacheKey = $cacheKey ?: 'credentials_' . crc32(gethostname());
98         } else {
99             // Instantiate using short or long term credentials
100             $credentials = new static(
101                 $config[Options::KEY],
102                 $config[Options::SECRET],
103                 $config[Options::TOKEN],
104                 $config[Options::TOKEN_TTD]
105             );
106             // If no cache key was set, use the access key ID
107             $cacheKey = $cacheKey ?: 'credentials_' . $config[Options::KEY];
108         }
109 
110         // Check if the credentials are refreshable, and if so, configure caching
111         $cache = $config[Options::CREDENTIALS_CACHE];
112         if ($cacheKey && $cache) {
113             $credentials = self::createCache($credentials, $cache, $cacheKey);
114         }
115 
116         return $credentials;
117     }
118 
119     /**
120      * Create credentials from the credentials ini file in the HOME directory.
121      *
122      * @param string|null $profile  Pass a specific profile to use. If no
123      *                              profile is specified we will attempt to use
124      *                              the value specified in the AWS_PROFILE
125      *                              environment variable. If AWS_PROFILE is not
126      *                              set, the "default" profile is used.
127      * @param string|null $filename Pass a string to specify the location of the
128      *                              credentials files. If null is passed, the
129      *                              SDK will attempt to find the configuration
130      *                              file at in your HOME directory at
131      *                              ~/.aws/credentials.
132      * @return CredentialsInterface
133      * @throws \RuntimeException if the file cannot be found, if the file is
134      *                           invalid, or if the profile is invalid.
135      */
136     public static function fromIni($profile = null, $filename = null)
137     {
138         if (!$filename) {
139             $filename = self::getHomeDir() . '/.aws/credentials';
140         }
141 
142         if (!$profile) {
143             $profile = self::getEnvVar(self::ENV_PROFILE) ?: 'default';
144         }
145 
146         if (!file_exists($filename) || !($data = parse_ini_file($filename, true))) {
147             throw new \RuntimeException("Invalid AWS credentials file: {$filename}.");
148         }
149 
150         if (empty($data[$profile])) {
151             throw new \RuntimeException("Invalid AWS credentials profile {$profile} in {$filename}.");
152         }
153 
154         return new self(
155             $data[$profile]['aws_access_key_id'],
156             $data[$profile]['aws_secret_access_key'],
157             isset($data[$profile]['aws_security_token'])
158                 ? $data[$profile]['aws_security_token']
159                 : null
160         );
161     }
162 
163     /**
164      * Constructs a new BasicAWSCredentials object, with the specified AWS
165      * access key and AWS secret key
166      *
167      * @param string $accessKeyId     AWS access key ID
168      * @param string $secretAccessKey AWS secret access key
169      * @param string $token           Security token to use
170      * @param int    $expiration      UNIX timestamp for when credentials expire
171      */
172     public function __construct($accessKeyId, $secretAccessKey, $token = null, $expiration = null)
173     {
174         $this->key = trim($accessKeyId);
175         $this->secret = trim($secretAccessKey);
176         $this->token = $token;
177         $this->ttd = $expiration;
178     }
179 
180     public function serialize()
181     {
182         return json_encode(array(
183             Options::KEY       => $this->key,
184             Options::SECRET    => $this->secret,
185             Options::TOKEN     => $this->token,
186             Options::TOKEN_TTD => $this->ttd
187         ));
188     }
189 
190     public function unserialize($serialized)
191     {
192         $data = json_decode($serialized, true);
193         $this->key    = $data[Options::KEY];
194         $this->secret = $data[Options::SECRET];
195         $this->token  = $data[Options::TOKEN];
196         $this->ttd    = $data[Options::TOKEN_TTD];
197     }
198 
199     public function getAccessKeyId()
200     {
201         return $this->key;
202     }
203 
204     public function getSecretKey()
205     {
206         return $this->secret;
207     }
208 
209     public function getSecurityToken()
210     {
211         return $this->token;
212     }
213 
214     public function getExpiration()
215     {
216         return $this->ttd;
217     }
218 
219     public function isExpired()
220     {
221         return $this->ttd !== null && time() >= $this->ttd;
222     }
223 
224     public function setAccessKeyId($key)
225     {
226         $this->key = $key;
227 
228         return $this;
229     }
230 
231     public function setSecretKey($secret)
232     {
233         $this->secret = $secret;
234 
235         return $this;
236     }
237 
238     public function setSecurityToken($token)
239     {
240         $this->token = $token;
241 
242         return $this;
243     }
244 
245     public function setExpiration($timestamp)
246     {
247         $this->ttd = $timestamp;
248 
249         return $this;
250     }
251 
252     /**
253      * When no keys are provided, attempt to create them based on the
254      * environment or instance profile credentials.
255      *
256      * @param array|Collection $config
257      *
258      * @return CredentialsInterface
259      */
260     private static function createFromEnvironment($config)
261     {
262         // Get key and secret from ENV variables
263         $envKey = self::getEnvVar(self::ENV_KEY);
264         if (!($envSecret = self::getEnvVar(self::ENV_SECRET))) {
265             // Use AWS_SECRET_ACCESS_KEY if AWS_SECRET_KEY was not set.
266             $envSecret = self::getEnvVar(self::ENV_SECRET_ACCESS_KEY);
267         }
268 
269         // Use credentials from the environment variables if available
270         if ($envKey && $envSecret) {
271             return new static($envKey, $envSecret);
272         }
273 
274         // Use credentials from the ini file in HOME directory if available
275         $home = self::getHomeDir();
276         if ($home && file_exists("{$home}/.aws/credentials")) {
277             return self::fromIni($config[Options::PROFILE], "{$home}/.aws/credentials");
278         }
279 
280         // Use instance profile credentials (available on EC2 instances)
281         return new RefreshableInstanceProfileCredentials(
282             new static('', '', '', 1),
283             $config[Options::CREDENTIALS_CLIENT]
284         );
285     }
286 
287     private static function createCache(CredentialsInterface $credentials, $cache, $cacheKey)
288     {
289         if ($cache === 'true' || $cache === true) {
290             // If no cache adapter was provided, then create one for the user
291             // @codeCoverageIgnoreStart
292             if (!extension_loaded('apc')) {
293                 throw new RequiredExtensionNotLoadedException('PHP has not been compiled with APC. Unable to cache '
294                     . 'the credentials.');
295             } elseif (!class_exists('Doctrine\Common\Cache\ApcCache')) {
296                 throw new RuntimeException(
297                     'Cannot set ' . Options::CREDENTIALS_CACHE . ' to true because the Doctrine cache component is '
298                     . 'not installed. Either install doctrine/cache or pass in an instantiated '
299                     . 'Guzzle\Cache\CacheAdapterInterface object'
300                 );
301             }
302             // @codeCoverageIgnoreEnd
303             $cache = new DoctrineCacheAdapter(new \Doctrine\Common\Cache\ApcCache());
304         } elseif (!($cache instanceof CacheAdapterInterface)) {
305             throw new InvalidArgumentException('Unable to utilize caching with the specified options');
306         }
307 
308         // Decorate the credentials with a cache
309         return new CacheableCredentials($credentials, $cache, $cacheKey);
310     }
311 
312     private static function getHomeDir()
313     {
314         // On Linux/Unix-like systems, use the HOME environment variable
315         if ($homeDir = self::getEnvVar('HOME')) {
316             return $homeDir;
317         }
318 
319         // Get the HOMEDRIVE and HOMEPATH values for Windows hosts
320         $homeDrive = self::getEnvVar('HOMEDRIVE');
321         $homePath = self::getEnvVar('HOMEPATH');
322 
323         return ($homeDrive && $homePath) ? $homeDrive . $homePath : null;
324     }
325 
326     /**
327      * Fetches the value of an environment variable by checking $_SERVER and getenv().
328      *
329      * @param string $var Name of the environment variable
330      *
331      * @return mixed|null
332      */
333     private static function getEnvVar($var)
334     {
335         return isset($_SERVER[$var]) ? $_SERVER[$var] : getenv($var);
336     }
337 }

