19 /**
20  * Abstract decorator to provide a foundation for refreshable credentials
21  */
22 abstract class AbstractRefreshableCredentials extends AbstractCredentialsDecorator
23 {
24     /**
25      * {@inheritdoc}
26      */
27     public function getAccessKeyId()
28     {
29         if ($this->credentials->isExpired()) {
30             $this->refresh();
31         }
32 
33         return $this->credentials->getAccessKeyId();
34     }
35 
36     /**
37      * {@inheritdoc}
38      */
39     public function getSecretKey()
40     {
