21 /**
22  * Credentials decorator used to implement caching credentials
23  */
24 class CacheableCredentials extends AbstractRefreshableCredentials
25 {
26     /**
27      * @var CacheAdapterInterface Cache adapter used to store credentials
28      */
29     protected $cache;
30 
31     /**
32      * @var string Cache key used to store the credentials
33      */
34     protected $cacheKey;
35 
36     /**
37      * CacheableCredentials is a decorator that decorates other credentials
38      *
39      * @param CredentialsInterface  $credentials Credentials to adapt
40      * @param CacheAdapterInterface $cache       Cache to use to store credentials
41      * @param string                $cacheKey    Cache key of the credentials
42      */
43     public function __construct(CredentialsInterface $credentials, CacheAdapterInterface $cache, $cacheKey)
44     {
45         $this->credentials = $credentials;
46         $this->cache = $cache;
47         $this->cacheKey = $cacheKey;
48     }
49 
50     /**
51      * Attempt to get new credentials from cache or from the adapted object
52      */
53     protected function refresh()
54     {
55         if (!$cache = $this->cache->fetch($this->cacheKey)) {
56             // The credentials were not found, so try again and cache if new
57             $this->credentials->getAccessKeyId();
58             if (!$this->credentials->isExpired()) {
59                 // The credentials were updated, so cache them
60                 $this->cache->save($this->cacheKey, $this->credentials, 3600);
61             }
62         } else {
63             // The credentials were found in cache, so update the adapter object
64             // if the cached credentials are not expired
65             if (!$cache->isExpired()) {
66                 $this->credentials->setAccessKeyId($cache->getAccessKeyId());
67                 $this->credentials->setSecretKey($cache->getSecretKey());
68                 $this->credentials->setSecurityToken($cache->getSecurityToken());
69                 $this->credentials->setExpiration($cache->getExpiration());
70             }
71         }
72     }
73 }

