21 class RefreshableRole extends AbstractRefreshableCredentials
22 {
23 	const ROLE_SESSION_NAME_PREFIX = "kaltura_s3_access_";
24 	const ASSUME_ROLE_CREDENTIALS_EXPIRY_TIME = 43200;
25 	
26 	private $roleArn = null;
27 	private $s3Region = null;
28 	
29 	public function refresh()
30 	{
31 		$credentialsCacheDir = sys_get_temp_dir() . DIRECTORY_SEPARATOR . 's3_creds_cache';
32 		
33 		$credentials = new Credentials('', '');
34 		$ipRefresh = new RefreshableInstanceProfileCredentials(new Credentials('', '', '', 1));
35 		$ipCache = new DoctrineCacheAdapter(new FilesystemCache("$credentialsCacheDir/instanceProfileCache"));
36 		$ipCreds = new CacheableCredentials($ipRefresh, $ipCache, 'refresh_role_creds_key');
37 		
38 		$stsFactoryParams = array(
39 			'credentials' => $ipCreds,
40 		);
41 		
42 		//Added to support regional STS endpoints in case external traffic is blocked
43 		if($this->s3Region)
44 		{
45 			$stsFactoryParams['region'] = $this->s3Region;
46 			$stsFactoryParams['endpoint'] = "https://sts.{$this->s3Region}.amazonaws.com";
47 		}
48 		
49 		$sts = StsClient::factory($stsFactoryParams);
50 		$call = $sts->assumeRole(array(
51 			'RoleArn' => $this->roleArn,
52 			'RoleSessionName' => self::ROLE_SESSION_NAME_PREFIX . date('m_d_G', time()),
53 			'DurationSeconds' => self::ASSUME_ROLE_CREDENTIALS_EXPIRY_TIME
54 		));
55 		
56 		$creds = $call['Credentials'];
57 		$result = new Credentials(
58 			$creds['AccessKeyId'],
59 			$creds['SecretAccessKey'],
60 			$creds['SessionToken'],
61 			strtotime($creds['Expiration'])
62 		);
63 		
64 		$this->credentials->setAccessKeyId($result->getAccessKeyId())
65 			->setSecretKey($result->getSecretKey())
66 			->setSecurityToken($result->getSecurityToken())
67 			->setExpiration($result->getExpiration());
68 		
69 		return $credentials;
70 	}
71 	
72 	public function setRoleArn($roleArn)
73 	{
74 		$this->roleArn = $roleArn;
75 	}
76 	
77 	public function setS3Region($s3Region)
78 	{
79 		$this->s3Region = $s3Region;
80 	}
81 }

