20 namespace Doctrine\Common\Cache;
21 
22 /**
23  * Base file cache driver.
24  *
25  * @since  2.3
26  * @author Fabio B. Silva <fabio.bat.silva@gmail.com>
27  */
28 abstract class FileCache extends CacheProvider
29 {
30     /**
31      * The cache directory.
32      *
33      * @var string
34      */
35     protected $directory;
36 
37     /**
38      * The cache file extension.
39      *
40      * @var string
41      */
42     private $extension;
43 
44     /**
45      * @var string[] regular expressions for replacing disallowed characters in file name
46      */
47     private $disallowedCharacterPatterns = array(
48         '/\-/', // replaced to disambiguate original `-` and `-` derived from replacements
49         '/[^a-zA-Z0-9\-_\[\]]/' // also excludes non-ascii chars (not supported, depending on FS)
50     );
51 
52     /**
53      * @var string[] replacements for disallowed file characters
54      */
55     private $replacementCharacters = array('__', '-');
56 
57     /**
58      * Constructor.
59      *
60      * @param string $directory The cache directory.
61      * @param string $extension The cache file extension.
62      *
63      * @throws \InvalidArgumentException
64      */
65     public function __construct($directory, $extension = '')
66     {
67         if ( ! is_dir($directory) && ! @mkdir($directory, 0777, true)) {
68             throw new \InvalidArgumentException(sprintf(
69                 'The directory "%s" does not exist and could not be created.',
70                 $directory
71             ));
72         }
73 
74         if ( ! is_writable($directory)) {
75             throw new \InvalidArgumentException(sprintf(
76                 'The directory "%s" is not writable.',
77                 $directory
78             ));
79         }
80 
81         $this->directory = realpath($directory);
82         $this->extension = (string) $extension;
83     }
84 
85     /**
86      * Gets the cache directory.
87      *
88      * @return string
89      */
90     public function getDirectory()
91     {
92         return $this->directory;
93     }
94 
95     /**
96      * Gets the cache file extension.
97      *
98      * @return string|null
99      */
100     public function getExtension()
101     {
102         return $this->extension;
103     }
104 
105     /**
106      * @param string $id
107      *
108      * @return string
109      */
110     protected function getFilename($id)
111     {
112         return $this->directory
113             . DIRECTORY_SEPARATOR
114             . implode(str_split(hash('sha256', $id), 2), DIRECTORY_SEPARATOR)
115             . DIRECTORY_SEPARATOR
116             . preg_replace($this->disallowedCharacterPatterns, $this->replacementCharacters, $id)
117             . $this->extension;
118     }
119 
120     /**
121      * {@inheritdoc}
122      */
123     protected function doDelete($id)
124     {
125         return @unlink($this->getFilename($id));
126     }
127 
128     /**
129      * {@inheritdoc}
130      */
131     protected function doFlush()
132     {
133         foreach ($this->getIterator() as $name => $file) {
134             @unlink($name);
135         }
136 
137         return true;
138     }
139 
140     /**
141      * {@inheritdoc}
142      */
143     protected function doGetStats()
144     {
145         $usage = 0;
146         foreach ($this->getIterator() as $file) {
147             $usage += $file->getSize();
148         }
149 
150         $free = disk_free_space($this->directory);
151 
152         return array(
153             Cache::STATS_HITS               => null,
154             Cache::STATS_MISSES             => null,
155             Cache::STATS_UPTIME             => null,
156             Cache::STATS_MEMORY_USAGE       => $usage,
157             Cache::STATS_MEMORY_AVAILABLE   => $free,
158         );
159     }
160 
161     /**
162      * Create path if needed.
163      *
164      * @param string $path
165      * @return bool TRUE on success or if path already exists, FALSE if path cannot be created.
166      */
167     private function createPathIfNeeded($path)
168     {
169         if ( ! is_dir($path)) {
170             if (false === @mkdir($path, 0777, true) && !is_dir($path)) {
171                 return false;
172             }
173         }
174 
175         return true;
176     }
177 
178     /**
179      * Writes a string content to file in an atomic way.
180      *
181      * @param string $filename Path to the file where to write the data.
182      * @param string $content  The content to write
183      *
184      * @return bool TRUE on success, FALSE if path cannot be created, if path is not writable or an any other error.
185      */
186     protected function writeFile($filename, $content)
187     {
188         $filepath = pathinfo($filename, PATHINFO_DIRNAME);
189 
190         if ( ! $this->createPathIfNeeded($filepath)) {
191             return false;
192         }
193 
194         if ( ! is_writable($filepath)) {
195             return false;
196         }
197 
198         $tmpFile = tempnam($filepath, 'swap');
199 
200         if (file_put_contents($tmpFile, $content) !== false) {
201             if (@rename($tmpFile, $filename)) {
202                 @chmod($filename, 0666 & ~umask());
203 
204                 return true;
205             }
206 
207             @unlink($tmpFile);
208         }
209 
210         return false;
211     }
212 
213     /**
214      * @return \Iterator
215      */
216     private function getIterator()
217     {
218         return new \RegexIterator(
219             new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($this->directory)),
220             '/^.+' . preg_quote($this->extension, '/') . '$/i'
221         );
222     }
223 }

