22 /**
23  * Base class for cache provider implementations.
24  *
25  * @since  2.2
26  * @author Benjamin Eberlei <kontakt@beberlei.de>
27  * @author Guilherme Blanco <guilhermeblanco@hotmail.com>
28  * @author Jonathan Wage <jonwage@gmail.com>
29  * @author Roman Borschel <roman@code-factory.org>
30  * @author Fabio B. Silva <fabio.bat.silva@gmail.com>
31  */
32 abstract class CacheProvider implements Cache, FlushableCache, ClearableCache, MultiGetCache
33 {
34     const DOCTRINE_NAMESPACE_CACHEKEY = 'DoctrineNamespaceCacheKey[%s]';
35 
36     /**
37      * The namespace to prefix all cache ids with.
38      *
39      * @var string
40      */
41     private $namespace = '';
42 
43     /**
44      * The namespace version.
45      *
46      * @var integer|null
47      */
48     private $namespaceVersion;
49 
50     /**
51      * Sets the namespace to prefix all cache ids with.
52      *
53      * @param string $namespace
54      *
55      * @return void
56      */
57     public function setNamespace($namespace)
58     {
59         $this->namespace        = (string) $namespace;
60         $this->namespaceVersion = null;
61     }
62 
63     /**
64      * Retrieves the namespace that prefixes all cache ids.
65      *
66      * @return string
67      */
68     public function getNamespace()
69     {
70         return $this->namespace;
71     }
72 
73     /**
74      * {@inheritdoc}
75      */
76     public function fetch($id)
77     {
78         return $this->doFetch($this->getNamespacedId($id));
79     }
80 
81     /**
82      * {@inheritdoc}
83      */
84     public function fetchMultiple(array $keys)
85     {
86         // note: the array_combine() is in place to keep an association between our $keys and the $namespacedKeys
87         $namespacedKeys = array_combine($keys, array_map(array($this, 'getNamespacedId'), $keys));
88         $items          = $this->doFetchMultiple($namespacedKeys);
89         $foundItems     = array();
90 
91         // no internal array function supports this sort of mapping: needs to be iterative
92         // this filters and combines keys in one pass
93         foreach ($namespacedKeys as $requestedKey => $namespacedKey) {
94             if (isset($items[$namespacedKey])) {
95                 $foundItems[$requestedKey] = $items[$namespacedKey];
96             }
97         }
98 
99         return $foundItems;
100     }
101 
102     /**
103      * {@inheritdoc}
104      */
105     public function contains($id)
106     {
107         return $this->doContains($this->getNamespacedId($id));
108     }
109 
110     /**
111      * {@inheritdoc}
112      */
113     public function save($id, $data, $lifeTime = 0)
114     {
115         return $this->doSave($this->getNamespacedId($id), $data, $lifeTime);
116     }
117 
118     /**
119      * {@inheritdoc}
120      */
121     public function delete($id)
122     {
123         return $this->doDelete($this->getNamespacedId($id));
124     }
125 
126     /**
127      * {@inheritdoc}
128      */
129     public function getStats()
130     {
131         return $this->doGetStats();
132     }
133 
134     /**
135      * {@inheritDoc}
136      */
137     public function flushAll()
138     {
139         return $this->doFlush();
140     }
141 
142     /**
143      * {@inheritDoc}
144      */
145     public function deleteAll()
146     {
147         $namespaceCacheKey = $this->getNamespaceCacheKey();
148         $namespaceVersion  = $this->getNamespaceVersion() + 1;
149 
150         $this->namespaceVersion = $namespaceVersion;
151 
152         return $this->doSave($namespaceCacheKey, $namespaceVersion);
153     }
154 
155     /**
156      * Prefixes the passed id with the configured namespace value.
157      *
158      * @param string $id The id to namespace.
159      *
160      * @return string The namespaced id.
161      */
162     private function getNamespacedId($id)
163     {
164         $namespaceVersion  = $this->getNamespaceVersion();
165 
166         return sprintf('%s[%s][%s]', $this->namespace, $id, $namespaceVersion);
167     }
168 
169     /**
170      * Returns the namespace cache key.
171      *
172      * @return string
173      */
174     private function getNamespaceCacheKey()
175     {
176         return sprintf(self::DOCTRINE_NAMESPACE_CACHEKEY, $this->namespace);
177     }
178 
179     /**
180      * Returns the namespace version.
181      *
182      * @return integer
183      */
184     private function getNamespaceVersion()
185     {
186         if (null !== $this->namespaceVersion) {
187             return $this->namespaceVersion;
188         }
189 
190         $namespaceCacheKey = $this->getNamespaceCacheKey();
191         $namespaceVersion = $this->doFetch($namespaceCacheKey);
192 
193         if (false === $namespaceVersion) {
194             $namespaceVersion = 1;
195 
196             $this->doSave($namespaceCacheKey, $namespaceVersion);
197         }
198 
199         $this->namespaceVersion = $namespaceVersion;
200 
201         return $this->namespaceVersion;
202     }
203 
204     /**
205      * Default implementation of doFetchMultiple. Each driver that supports multi-get should owerwrite it.
206      *
207      * @param array $keys Array of keys to retrieve from cache
208      * @return array Array of values retrieved for the given keys.
209      */
210     protected function doFetchMultiple(array $keys)
211     {
212         $returnValues = array();
213 
214         foreach ($keys as $index => $key) {
215             if (false !== ($item = $this->doFetch($key))) {
216                 $returnValues[$key] = $item;
217             }
218         }
219 
220         return $returnValues;
221     }
222 
223     /**
224      * Fetches an entry from the cache.
225      *
226      * @param string $id The id of the cache entry to fetch.
227      *
228      * @return string|boolean The cached data or FALSE, if no cache entry exists for the given id.
229      */
230     abstract protected function doFetch($id);
231 
232     /**
233      * Tests if an entry exists in the cache.
234      *
235      * @param string $id The cache id of the entry to check for.
236      *
237      * @return boolean TRUE if a cache entry exists for the given cache id, FALSE otherwise.
238      */
239     abstract protected function doContains($id);
240 
241     /**
242      * Puts data into the cache.
243      *
244      * @param string $id       The cache id.
245      * @param string $data     The cache entry/data.
246      * @param int    $lifeTime The lifetime. If != 0, sets a specific lifetime for this
247      *                           cache entry (0 => infinite lifeTime).
248      *
249      * @return boolean TRUE if the entry was successfully stored in the cache, FALSE otherwise.
250      */
251     abstract protected function doSave($id, $data, $lifeTime = 0);
252 
253     /**
254      * Deletes a cache entry.
255      *
256      * @param string $id The cache id.
257      *
258      * @return boolean TRUE if the cache entry was successfully deleted, FALSE otherwise.
259      */
260     abstract protected function doDelete($id);
261 
262     /**
263      * Flushes all cache entries.
264      *
265      * @return boolean TRUE if the cache entry was successfully deleted, FALSE otherwise.
266      */
267     abstract protected function doFlush();
268 
269     /**
270      * Retrieves cached information from the data store.
271      *
272      * @since 2.2
273      *
274      * @return array|null An associative array with server's statistics if available, NULL otherwise.
275      */
276     abstract protected function doGetStats();
277 }

